INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5300, 'protest', '/prəˈtɛst/', 'verb', '{"zh-TW":["抗議；反對"],"en":["to express strong disagreement"]}', '{"prefix":{"text":"pro-","meaning":"forth"},"root":{"text":"test","meaning":"witness (證明)"}}', 'protest against / stage a protest / file a protest', '[{"en":"Workers protested against the pay cuts.","zh-TW":"工人抗議減薪。"},{"en":"The decision was met with strong protests.","zh-TW":"該決定遭到強烈抗議。"}]', '{"noun":"protest, protester"}', NULL, 3, 5300, NULL),
(5301, 'protocol', '/ˈproʊtəkɒl/', 'noun', '{"zh-TW":["協議；通訊協定"],"en":["a set of rules for transmitting data"]}', NULL, 'security protocol / communication protocol', '[{"en":"Follow the security protocol.","zh-TW":"遵循安全協議。"},{"en":"HTTP is a communication protocol.","zh-TW":"HTTP是一種通訊協定。"}]', NULL, NULL, 3, 5301, 427),
(5302, 'prototype', '/ˈproʊtətaɪp/', 'noun', '{"zh-TW":["原型；雛形"],"en":["a preliminary model of a product used for testing and feedback"]}', NULL, 'build a prototype / prototype testing / functional prototype', '[{"en":"The team built a prototype in two weeks to test the concept.","zh-TW":"團隊在兩週內建立了一個原型來測試概念。"},{"en":"User feedback on the prototype led to significant design changes.","zh-TW":"對原型的用戶反饋導致了重大的設計更改。"}]', '{"verb":"prototype"}', NULL, 3, 5302, NULL),
(5303, 'proud', '/praʊd/', 'adjective', '{"zh-TW":["驕傲的；自豪的"],"en":["feeling pleasure about one''s achievements","feeling deep pleasure from one''s own achievements"]}', '{"root":{"text":"proud","meaning":"valiant (英勇)"},"logic":"源自古法語 prud（英勇的），後指對自身感到光榮。"}', 'proud of / proud moment', '[{"en":"We are proud of our team''s achievement.","zh-TW":"我們為團隊的成就感到自豪。"},{"en":"This is a proud moment for the company.","zh-TW":"這是公司引以為傲的時刻。"},{"en":"Her parents are proud of her accomplishments.","zh-TW":"她的父母為她的成就感到驕傲。"},{"en":"It was a proud moment for the whole team.","zh-TW":"這是全隊引以為傲的時刻。"}]', '{"adjective":"proud","noun":"pride","adverb":"proudly"}', NULL, 2, 5303, NULL),
(5304, 'prove', '/pruːv/', 'verb', '{"zh-TW":["證明；證實"],"en":["to show that something is true"]}', NULL, 'prove that / prove to be / prove successful', '[{"en":"The data proved our hypothesis correct.","zh-TW":"數據證明我們的假設正確。"},{"en":"The investment proved to be profitable.","zh-TW":"投資被證明是有利可圖的。"}]', '{"noun":"proof","adjective":"proven"}', NULL, 2, 5304, NULL),
(5305, 'provenance', '/ˈprɒvənəns/', 'noun', '{"zh-TW":["來源；出處"],"en":["the origin or source of something"]}', NULL, 'establish provenance / data provenance / art provenance', '[{"en":"Blockchain can verify the provenance of goods in supply chains.","zh-TW":"區塊鏈可以驗證供應鏈中商品的來源。"},{"en":"Questions about the artwork''s provenance led to its removal from auction.","zh-TW":"關於這件藝術品來源的問題導致其從拍賣會中撤出。"}]', '{"adjective":"provenant"}', NULL, 4, 5305, NULL),
(5306, 'provide', '/prəˈvaɪd/', 'verb', '{"zh-TW":["提供"],"en":["to give or supply something"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"vide","meaning":"see (看)"}}', 'provide services / provide information / provide support', '[{"en":"We provide 24/7 customer support.","zh-TW":"我們提供全天候客服支援。"},{"en":"The report provides useful information.","zh-TW":"報告提供了有用資訊。"}]', '{"noun":"provider, provision","adjective":"provided"}', NULL, 3, 5306, 188),
(5307, 'provision', '/prəˈvɪʒən/', 'noun', '{"zh-TW":["規定；條款","供應"],"en":["a condition in a law or agreement","the act of providing"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"vis","meaning":"see (看)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'make provisions for / under the provisions of / provision of services', '[{"en":"The contract includes a provision for early termination.","zh-TW":"合約包含提前終止的條款。"},{"en":"Make provisions for unexpected expenses.","zh-TW":"為意外開支做好準備。"}]', '{"adjective":"provisional","verb":"provision"}', NULL, 3, 5307, 428),
(5308, 'provisional', '/prəˈvɪʒənəl/', 'adjective', '{"zh-TW":["臨時的；暫行的"],"en":["arranged for the present, with the possibility of change"]}', NULL, 'provisional agreement / provisional findings / provisional result', '[{"en":"The committee issued a provisional report pending further review.","zh-TW":"委員會在進一步審查之前發布了一份臨時報告。"},{"en":"The provisional findings suggest a link between diet and cognition.","zh-TW":"臨時研究結果顯示飲食與認知之間存在關聯。"}]', '{"adverb":"provisionally","noun":"provision"}', NULL, 4, 5308, NULL),
(5309, 'provisional agreement', '/prəˈvɪʒənl əˈɡriːmənt/', 'noun', '{"zh-TW":["臨時協議；暫時協議"],"en":["a temporary agreement pending finalization of a formal contract"]}', NULL, 'sign a provisional agreement / provisional agreement terms', '[{"en":"A provisional agreement was signed pending legal review.","zh-TW":"在法律審查待定期間簽署了臨時協議。"},{"en":"The provisional agreement will expire if not converted to a final contract.","zh-TW":"如果沒有轉換為最終合約，臨時協議將失效。"}]', NULL, NULL, 5, 5309, NULL),
(5310, 'provoke', '/prəˈvoʊk/', 'verb', '{"zh-TW":["激起；引發"],"en":["to cause a reaction; to anger"]}', '{"prefix":{"text":"pro-","meaning":"forth"},"root":{"text":"voke","meaning":"call (召喚)"}}', 'provoke a response / provoke debate / provoke anger', '[{"en":"The announcement provoked strong reactions.","zh-TW":"公告引起了強烈反應。"},{"en":"His comments provoked a heated debate.","zh-TW":"他的評論引發了激烈辯論。"}]', '{"noun":"provocation","adjective":"provocative"}', NULL, 3, 5310, NULL),
(5311, 'proximity', '/''prɒkˌsɪməti/', 'noun', '{"zh-TW":["接近；鄰近"],"en":["nearness in space, time, or relationship"]}', NULL, 'close proximity / in proximity to / physical proximity', '[{"en":"The office''s proximity to public transportation makes it convenient for employees.","zh-TW":"辦公室靠近公共交通，方便員工出行。"},{"en":"Living in close proximity to family gives her a strong sense of security.","zh-TW":"住在距家人很近的地方給了她強烈的安全感。"}]', '{"adjective":"proximate","adverb":"proximately"}', NULL, 3, 5311, NULL),
(5312, 'proxy voting', '/ˈprɒksi ˈvoʊtɪŋ/', 'noun', '{"zh-TW":["委託投票；代理投票"],"en":["voting on behalf of a shareholder who cannot attend a meeting"]}', NULL, 'use proxy voting / proxy voting form', '[{"en":"Shareholders submitted proxy voting forms before the AGM.","zh-TW":"股東在年度股東大會前提交了委託投票表格。"},{"en":"Proxy voting allows institutional investors to vote on behalf of clients.","zh-TW":"委託投票允許機構投資者代表客戶投票。"}]', NULL, NULL, 4, 5312, NULL),
(5313, 'psychiatry', '/saɪˈkaɪətri/', 'noun', '{"zh-TW":["精神病學；精神科"],"en":["the branch of medicine dealing with mental disorders"]}', NULL, 'psychiatry consultation / psychiatry treatment', '[{"en":"She was referred to psychiatry for depression treatment.","zh-TW":"她被轉介到精神科接受憂鬱症治療。"},{"en":"Psychiatry combines medication and therapy to treat mental illness.","zh-TW":"精神科結合藥物和療法來治療精神疾病。"}]', '{"noun":"psychiatrist","adjective":"psychiatric"}', NULL, 4, 5313, NULL),
(5314, 'psychographic', '/ˌsaɪkəˈɡræfɪk/', 'adjective', '{"zh-TW":["心理圖像的；心理統計的"],"en":["relating to personality, values, lifestyles, and interests of consumers"]}', NULL, 'psychographic segmentation / psychographic profile / psychographic targeting', '[{"en":"Psychographic segmentation helped craft messages that resonated emotionally.","zh-TW":"心理圖像細分幫助製作了能引起情感共鳴的訊息。"},{"en":"The campaign used psychographic data to target eco-conscious consumers.","zh-TW":"該活動使用心理統計數據來針對有環保意識的消費者。"}]', '{"noun":"psychographics"}', NULL, 5, 5314, NULL),
(5315, 'public', '/ˈpʌblɪk/', 'adjective', '{"zh-TW":["公共的；公眾的"],"en":["relating to people in general"]}', '{"root":{"text":"publ","meaning":"people (人民)"}}', 'public sector / public opinion / go public', '[{"en":"The company plans to go public next year.","zh-TW":"公司計劃明年上市。"},{"en":"Public transportation is convenient here.","zh-TW":"這裡的公共交通很方便。"}]', '{"noun":"public, publicity","adverb":"publicly","verb":"publicize"}', NULL, 2, 5315, NULL),
(5316, 'public company', '/ˈpʌblɪk ˈkʌmpəni/', 'noun', '{"zh-TW":["公眾公司；上市公司"],"en":["a company whose shares are traded on a public stock exchange"]}', NULL, 'listed as a public company / public company disclosure', '[{"en":"Becoming a public company requires meeting stock exchange requirements.","zh-TW":"成為上市公司需要滿足股票交易所的要求。"},{"en":"A public company must publish quarterly financial results.","zh-TW":"上市公司必須公布季度財務業績。"}]', '{"opposite":"private company"}', NULL, 5, 5316, NULL),
(5317, 'public debt', '/''pʌblɪk det/', 'noun', '{"zh-TW":["公共債務；國家債務"],"en":["the total amount of money that a government owes to its creditors"]}', NULL, 'manage public debt / reduce public debt / public debt crisis', '[{"en":"High levels of public debt can limit a government''s ability to respond to economic crises.","zh-TW":"高水平的公共債務可能限制政府應對經濟危機的能力。"},{"en":"The government introduced austerity measures to reduce public debt while maintaining essential services.","zh-TW":"政府引入緊縮措施，在維持基本服務的同時減少公共債務。"}]', '{"adjective":"public","noun2":"debt"}', NULL, 4, 5317, NULL),
(5318, 'public goods', '/ˈpʌblɪk ɡʊdz/', 'noun', '{"zh-TW":["公共財"],"en":["goods that are non-excludable and non-rival in consumption, such as clean air"]}', NULL, 'provide public goods / free-rider problem with public goods / public goods theory', '[{"en":"National defense and clean air are classic examples of public goods.","zh-TW":"國防和清潔空氣是公共財的典型例子。"},{"en":"Because public goods cannot be denied to non-payers, they are typically provided by government.","zh-TW":"由於公共財不能拒絕向不付費者提供，它們通常由政府提供。"}]', NULL, NULL, 4, 5318, NULL),
(5319, 'public listing', '/ˈpʌblɪk ˈlɪstɪŋ/', 'noun', '{"zh-TW":["上市；公開掛牌"],"en":["the process of offering company shares to the public on a stock exchange"]}', NULL, 'achieve a public listing / plan a public listing', '[{"en":"The company achieved a public listing after five years of private operation.","zh-TW":"公司在五年私人運營後實現了上市。"},{"en":"A public listing increases access to capital and raises brand profile.","zh-TW":"公開上市增加了資本獲取渠道並提升了品牌形象。"}]', NULL, NULL, 5, 5319, NULL),
(5320, 'public offering', '/ˈpʌblɪk ˈɒfərɪŋ/', 'noun', '{"zh-TW":["公開發行；公開招募"],"en":["the sale of securities to the general public, typically via a stock exchange"]}', NULL, 'complete a public offering / initial public offering', '[{"en":"The company raised $200 million through a public offering on the stock exchange.","zh-TW":"公司通過股票交易所的公開發行籌集了2億元。"},{"en":"A public offering requires compliance with securities regulations.","zh-TW":"公開發行需要遵守證券法規。"}]', '{"abbreviation":"IPO (initial public offering)"}', NULL, 5, 5320, NULL),
(5321, 'public procurement', '/ˈpʌblɪk prəˈkjʊərmənt/', 'noun', '{"zh-TW":["公共採購；政府採購"],"en":["the purchase of goods, services, and works by government entities"]}', NULL, 'participate in public procurement / public procurement rules', '[{"en":"Public procurement must follow strict transparency and fairness rules.","zh-TW":"公共採購必須遵守嚴格的透明度和公平性規則。"},{"en":"The company won its largest public procurement contract.","zh-TW":"公司贏得了最大的公共採購合約。"}]', NULL, NULL, 5, 5321, NULL),
(5322, 'public relations', '/ˈpʌblɪk rɪˈleɪʃənz/', 'noun', '{"zh-TW":["公共關係；公關"],"en":["managing the spread of information between an organization and the public"]}', NULL, 'PR campaign / handle public relations / public relations firm', '[{"en":"The public relations team managed the crisis communication effectively.","zh-TW":"公關團隊有效地管理了危機溝通。"},{"en":"Strong public relations can rebuild a damaged brand reputation.","zh-TW":"強大的公共關係可以重建受損的品牌聲譽。"}]', '{"abbreviation":"PR","adjective":"public-facing"}', NULL, 5, 5322, NULL),
(5323, 'public speaking', '/''pʌblɪk ˌspiːkɪŋ/', 'noun', '{"zh-TW":["公開演講；公眾演說"],"en":["the act of delivering a speech or presentation to a live audience"]}', NULL, 'improve public speaking / public speaking training / public speaking anxiety', '[{"en":"Public speaking is consistently ranked as one of the most common fears.","zh-TW":"公開演講一直被列為最常見的恐懼之一。"},{"en":"She practiced public speaking by joining a toastmasters club.","zh-TW":"她通過加入演講俱樂部來練習公開演講。"}]', NULL, NULL, 5, 5323, NULL),
(5324, 'publication', '/ˌpʌblɪˈkeɪʃən/', 'noun', '{"zh-TW":["出版；發表","出版物"],"en":["the act of publishing","a published work"]}', '{"root":{"text":"public","meaning":"public (公共)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'date of publication / scientific publication', '[{"en":"The publication of the report is scheduled for May.","zh-TW":"報告預定五月出版。"},{"en":"She has many academic publications.","zh-TW":"她有很多學術發表。"}]', '{"verb":"publish","noun":"publisher"}', NULL, 4, 5324, NULL),
(5325, 'publish', '/ˈpʌblɪʃ/', 'verb', '{"zh-TW":["出版；發表"],"en":["to make available to the public"]}', '{"root":{"text":"publ","meaning":"people (人民)"},"suffix":{"text":"-ish","meaning":"使..."}}', 'publish a report / publish online / newly published', '[{"en":"The findings were published in a journal.","zh-TW":"研究結果發表在期刊上。"},{"en":"We will publish the results online.","zh-TW":"我們將在網上公佈結果。"}]', '{"noun":"publication, publisher, publishing"}', NULL, 3, 5325, NULL),
(5326, 'pull', '/pʊl/', 'verb', '{"zh-TW":["拉；撤回"],"en":["to draw toward oneself","to withdraw"]}', NULL, 'pull out / pull together', '[{"en":"The investor decided to pull out.","zh-TW":"投資者決定撤資。"},{"en":"Let''s pull together on this project.","zh-TW":"讓我們在這個專案上齊心協力。"}]', '{"verb":"pull","noun":"pull"}', NULL, 1, 5326, NULL),
(5327, 'pulmonologist', '/ˌpʌlməˈnɒlədʒɪst/', 'noun', '{"zh-TW":["肺科醫師"],"en":["a physician specializing in diseases of the lungs and respiratory system"]}', NULL, 'consult a pulmonologist / specialized pulmonologist / experienced pulmonologist', '[{"en":"The pulmonologist diagnosed the patient with chronic obstructive pulmonary disease.","zh-TW":"肺科醫師診斷患者患有慢性阻塞性肺病。"},{"en":"Breathing difficulties that persist should be evaluated by a pulmonologist.","zh-TW":"持續的呼吸困難應由肺科醫師評估。"}]', NULL, NULL, 5, 5327, NULL),
(5328, 'punitive', '/ˈpjuːnɪtɪv/', 'adjective', '{"zh-TW":["懲罰性的；處罰的"],"en":["intended to punish severely or deter future behavior"]}', NULL, 'punitive damages / punitive measures / punitive taxation', '[{"en":"The court awarded punitive damages to deter the company from future misconduct.","zh-TW":"法院判定懲罰性賠償，以阻止公司未來的不當行為。"},{"en":"Punitive tariffs were imposed on imports to retaliate against trade violations.","zh-TW":"對進口商品徵收了懲罰性關稅，以報復貿易違規行為。"}]', '{"adverb":"punitively","noun":"punitiveness"}', NULL, 3, 5328, NULL),
(5329, 'punitive damages', '/ˈpjuːnɪtɪv ˈdæmɪdʒɪz/', 'noun', '{"zh-TW":["懲罰性賠償"],"en":["damages awarded above actual losses to punish particularly egregious conduct"]}', NULL, 'award punitive damages / seek punitive damages / punitive damages claim', '[{"en":"The jury awarded punitive damages for the company''s deliberate misconduct.","zh-TW":"陪審團因公司蓄意不當行為而判給懲罰性賠償。"},{"en":"Punitive damages deter future wrongdoing by other potential defendants.","zh-TW":"懲罰性賠償阻止其他潛在被告的未來不當行為。"}]', NULL, NULL, 5, 5329, NULL),
(5330, 'purchase', '/ˈpɜːrtʃəs/', 'verb', '{"zh-TW":["購買"],"en":["to buy something"]}', '{"prefix":{"text":"pur-","meaning":"forward (向前)"},"root":{"text":"chase","meaning":"pursue (追求)"},"logic":"向前追求某物，即「購買」。"}', 'make a purchase / purchase order; purchase order / purchase online / make a purchase', '[{"en":"Customers can purchase tickets online.","zh-TW":"顧客可以在線上購票。"},{"en":"She made a large purchase at the department store.","zh-TW":"她在百貨公司大量購物。"},{"en":"Customers can purchase products online.","zh-TW":"客戶可以在線上購買產品。"},{"en":"Please fill out a purchase order form.","zh-TW":"請填寫採購訂單。"}]', '{"noun":"purchase","noun2":"purchaser"}', NULL, 3, 5330, 48),
(5331, 'purchase agreement', '/ˈpɜːrtʃɪs əˈɡriːmənt/', 'noun', '{"zh-TW":["購買協議；買賣合約"],"en":["a contract for the sale of goods or property"]}', NULL, 'sign a purchase agreement / terms of purchase agreement', '[{"en":"A purchase agreement was signed before the handover.","zh-TW":"在移交前簽署了購買協議。"},{"en":"Review the purchase agreement carefully before signing.","zh-TW":"簽署前請仔細審查購買協議。"}]', NULL, NULL, 5, 5331, NULL),
(5332, 'purchase ledger', '/ˈpɜːrtʃɪs ˈledʒər/', 'noun', '{"zh-TW":["採購分類帳；應付帳款總帳"],"en":["a book of accounts recording all purchases made by a business"]}', NULL, 'update the purchase ledger / purchase ledger reconciliation', '[{"en":"All supplier invoices are posted to the purchase ledger.","zh-TW":"所有供應商發票都被過帳到採購分類帳。"},{"en":"The purchase ledger is reconciled monthly against supplier statements.","zh-TW":"採購分類帳每月根據供應商對帳單進行核對。"}]', NULL, NULL, 5, 5332, NULL),
(5333, 'purchase order', '/ˈpɜːrtʃəs ˈɔːrdər/', 'noun', '{"zh-TW":["採購訂單"],"en":["a commercial document authorizing a purchase from a supplier"]}', NULL, 'issue a purchase order / approve a purchase order / purchase order number', '[{"en":"A purchase order was raised for the new office furniture.","zh-TW":"為新辦公室家具開立了採購訂單。"},{"en":"Payment will be processed once the purchase order is approved.","zh-TW":"採購訂單獲批後將處理付款。"}]', '{"abbreviation":"PO"}', NULL, 5, 5333, NULL),
(5334, 'purchase requisition', '/ˈpɜːrtʃəs ˌrekwɪˈzɪʃən/', 'noun', '{"zh-TW":["採購申請單"],"en":["an internal document requesting authorization to purchase goods or services"]}', NULL, 'submit a purchase requisition / purchase requisition form', '[{"en":"A purchase requisition must be approved before placing an order.","zh-TW":"採購申請單必須在下訂單前獲得批准。"},{"en":"The purchase requisition process ensures budget compliance.","zh-TW":"採購申請單流程確保了預算合規性。"}]', NULL, NULL, 5, 5334, NULL),
(5335, 'purchaser', '/ˈpɜːrtʃɪsər/', 'noun', '{"zh-TW":["買方；採購方"],"en":["a person or organization that buys goods, services, or assets"]}', NULL, 'identify the purchaser / contract with the purchaser', '[{"en":"The purchaser requested modifications to the standard delivery terms.","zh-TW":"買方要求對標準交貨條款進行修改。"},{"en":"The purchaser must pay within 30 days of receiving the goods.","zh-TW":"買方必須在收到貨物後30天內付款。"}]', '{"verb":"purchase","noun2":"purchase"}', NULL, 3, 5335, NULL),
(5336, 'purchasing power', '/ˈpɜːrtʃəsɪŋ ˈpaʊər/', 'noun', '{"zh-TW":["購買力"],"en":["the ability of a person or organization to buy goods and services"]}', NULL, 'increase purchasing power / maintain purchasing power', '[{"en":"High inflation erodes the purchasing power of consumers.","zh-TW":"高通脹侵蝕了消費者的購買力。"},{"en":"A weaker currency reduces the purchasing power of imports.","zh-TW":"較弱的貨幣降低了進口商品的購買力。"}]', NULL, NULL, 5, 5336, NULL),
(5337, 'purpose', 'ˈpɜːrpəs', 'noun', '{"zh-TW":["目的；用途","意圖"],"en":["the reason for doing something","an intended result"]}', NULL, 'main purpose/on purpose', '[{"en":"What is the purpose of this meeting?","zh-TW":"這次會議的目的是什麼？"}]', '{"verb":"purpose","adjective":"purposeful","adverb":"purposefully"}', NULL, 3, 5337, NULL),
(5338, 'pursue', '/pərˈsjuː/', 'verb', '{"zh-TW":["追求；追趕","追求；從事","追求"],"en":["to follow in order to catch","to seek to achieve","to follow or try to achieve","to follow or work toward"]}', '{"prefix":{"text":"pur-","meaning":"forward (向前)"},"root":{"text":"sue","meaning":"follow (跟隨)"},"logic":"向前跟隨追趕，即「追求」。"}', 'pursue a career / pursue a goal / pursue happiness; pursue a career / pursue a goal / pursue opportunities; pursue a career / pursue excellence / pursue a goal', '[{"en":"She decided to pursue a career in medicine.","zh-TW":"她決定追求醫學事業。"},{"en":"He pursued his dream of becoming a writer.","zh-TW":"他追求成為作家的夢想。"},{"en":"She decided to pursue a career in finance.","zh-TW":"她決定從事金融事業。"},{"en":"We will continue to pursue this opportunity.","zh-TW":"我們將繼續追求這機會。"},{"en":"She decided to pursue a master''s degree.","zh-TW":"她決定攻讀碩士學位。"},{"en":"The company pursues excellence in all areas.","zh-TW":"公司在所有領域追求卓越。"}]', '{"noun":"pursuit"}', NULL, 2, 5338, NULL),
(5339, 'push', '/pʊʃ/', 'verb', '{"zh-TW":["推；推動"],"en":["to press forward","to urge strongly"]}', NULL, 'push forward / push back', '[{"en":"We need to push forward with the plan.","zh-TW":"我們需要推進計畫。"},{"en":"The client pushed back on the price.","zh-TW":"客戶對價格提出了異議。"}]', '{"verb":"push","noun":"push"}', NULL, 1, 5339, NULL),
(5340, 'put', '/pʊt/', 'verb', '{"zh-TW":["放置；表達"],"en":["to move to a position","to express"]}', NULL, 'put in place / put simply', '[{"en":"Let me put it simply.","zh-TW":"讓我簡單地說。"},{"en":"New measures have been put in place.","zh-TW":"新措施已經到位。"}]', '{"verb":"put","noun":"input","noun2":"output"}', NULL, 1, 5340, NULL),
(5341, 'Q&A session', '/kjuː ænd eɪ ˈsɛʃən/', 'noun', '{"zh-TW":["問答環節"],"en":["a period during or after a presentation for questions"]}', NULL, 'open a Q&A session / Q&A session questions', '[{"en":"The speaker opened the floor for a Q&A session.","zh-TW":"演講者開放了問答環節。"},{"en":"Please hold your questions until the Q&A session at the end.","zh-TW":"請將您的問題留到最後的問答環節。"}]', NULL, NULL, 4, 5341, NULL),
(5342, 'qualification', '/ˌkwɒlɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["資格；資質"],"en":["a skill or achievement that makes someone suitable for a job"]}', NULL, 'professional qualification / required qualification', '[{"en":"The job requires a professional qualification in accounting.","zh-TW":"這份工作需要會計專業資格。"},{"en":"Her qualifications made her the ideal candidate.","zh-TW":"她的資格使她成為理想候選人。"}]', '{"verb":"qualify","adjective":"qualified"}', NULL, 5, 5342, 429),
(5343, 'qualified', 'ˈkwɒlɪfaɪd', 'adjective', '{"zh-TW":["有資格的；合格的","具備條件的"],"en":["having the necessary skills","meeting required standards"]}', NULL, 'qualified candidate/highly qualified', '[{"en":"All qualified applicants will be considered.","zh-TW":"所有符合資格的申請人將被考慮。"}]', '{"verb":"qualify","noun":"qualification"}', NULL, 3, 5343, NULL),
(5344, 'qualified opinion', '/ˈkwɒlɪfaɪd əˈpɪnjən/', 'noun', '{"zh-TW":["保留意見；附條件意見"],"en":["an auditor''s report indicating minor reservations about financial statements"]}', NULL, 'issue a qualified opinion / qualified opinion disclosure', '[{"en":"The auditor issued a qualified opinion due to limitations in inventory verification.","zh-TW":"審計師由於庫存核查的限制發出了保留意見。"},{"en":"A qualified opinion does not mean the financial statements are materially misstated.","zh-TW":"保留意見並不意味著財務報表存在重大錯誤陳述。"}]', '{"opposite":"unqualified opinion"}', NULL, 5, 5344, NULL),
(5345, 'qualify', '/ˈkwɒlɪfaɪ/', 'verb', '{"zh-TW":["使有資格；符合條件"],"en":["to have the right to do something"]}', '{"root":{"text":"qual","meaning":"what kind (什麼樣)"},"suffix":{"text":"-ify","meaning":"使...化"}}', 'qualify for / well-qualified / qualify as', '[{"en":"You must qualify for the loan before applying.","zh-TW":"申請前你必須符合貸款資格。"},{"en":"She is well-qualified for the position.","zh-TW":"她非常適合這個職位。"}]', '{"noun":"qualification","adjective":"qualified, qualifying"}', NULL, 3, 5345, 49),
(5346, 'qualitative', '/ˈkwɒlɪtətɪv/', 'adjective', '{"zh-TW":["質性的；定性的"],"en":["relating to, measuring, or measured by the quality of something"]}', NULL, 'qualitative research / qualitative analysis / qualitative data', '[{"en":"The qualitative study explored participants'' lived experiences.","zh-TW":"這項質性研究探索了參與者的生活經驗。"},{"en":"Qualitative and quantitative methods complement each other.","zh-TW":"質性和量化方法相互補充。"}]', '{"adverb":"qualitatively"}', NULL, 4, 5346, NULL),
(5347, 'qualitative research', '/''kwɒlɪˌteɪtɪv rɪˌsɜːrtʃ/', 'noun', '{"zh-TW":["定性研究"],"en":["a type of research that explores phenomena through non-numerical data such as interviews, observations, and texts"]}', NULL, 'conduct qualitative research / qualitative research method / qualitative research finding', '[{"en":"Qualitative research helps capture the nuanced experiences of participants that numbers alone cannot convey.","zh-TW":"定性研究有助於捕捉數字本身無法傳達的參與者的細緻體驗。"},{"en":"She combined qualitative and quantitative research to gain a fuller understanding of the issue.","zh-TW":"她結合了定性和定量研究，以更全面地理解這個問題。"}]', '{"adjective":"qualitative","adverb":"qualitatively"}', NULL, 5, 5347, NULL),
(5348, 'quality', 'ˈkwɒlɪti', 'noun', '{"zh-TW":["品質；質量","特性"],"en":["the standard of something","a characteristic"]}', NULL, 'product quality/quality control', '[{"en":"We never compromise on quality.","zh-TW":"我們從不妥協品質。"}]', '{"adjective":"qualitative","adverb":"qualitatively"}', NULL, 3, 5348, NULL),
(5349, 'quality assurance', '/ˈkwɒlɪti əˈʃʊərəns/', 'noun', '{"zh-TW":["品質保證"],"en":["systematic processes ensuring products meet defined quality standards"]}', NULL, 'quality assurance process / quality assurance team / quality assurance testing', '[{"en":"Quality assurance testing caught critical bugs before the launch.","zh-TW":"品質保證測試在上市前發現了關鍵錯誤。"},{"en":"A quality assurance framework was implemented across production lines.","zh-TW":"在生產線上實施了品質保證框架。"}]', '{"abbreviation":"QA","adjective":"quality-assured"}', NULL, 5, 5349, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5350, 'quality assurance program', '/ˈkwɒlɪti əˈʃʊərəns ˈproʊɡræm/', 'noun', '{"zh-TW":["品質保證計劃"],"en":["a systematic program designed to ensure products or services meet standards"]}', NULL, 'implement a quality assurance program / quality assurance program audit', '[{"en":"The quality assurance program reduced product defects by 25%.","zh-TW":"品質保證計劃將產品缺陷減少了25%。"},{"en":"All suppliers must comply with the company''s quality assurance program.","zh-TW":"所有供應商必須遵守公司的品質保證計劃。"}]', NULL, NULL, 5, 5350, NULL),
(5351, 'quality circle', '/ˈkwɒlɪti ˈsɜːrkəl/', 'noun', '{"zh-TW":["品質圈"],"en":["a small group of workers who meet regularly to identify and solve quality problems"]}', NULL, 'form a quality circle / quality circle meeting', '[{"en":"Quality circles helped reduce defects in the manufacturing line.","zh-TW":"品質圈幫助減少了製造線上的缺陷。"},{"en":"Employees in the quality circle proposed process improvements.","zh-TW":"品質圈中的員工提出了流程改進建議。"}]', NULL, NULL, 5, 5351, NULL),
(5352, 'quality control', '/ˈkwɒlɪti kənˈtroʊl/', 'noun', '{"zh-TW":["品質管制"],"en":["processes ensuring products meet specified quality standards"]}', NULL, 'quality control checks / quality control process / implement quality control', '[{"en":"Rigorous quality control reduced defect rates to under 1%.","zh-TW":"嚴格的品質管制將缺陷率降至1%以下。"},{"en":"Quality control inspectors check every batch before shipment.","zh-TW":"品質管制檢查員在裝運前檢查每個批次。"}]', '{"abbreviation":"QC","noun":"quality controller"}', NULL, 5, 5352, NULL),
(5353, 'quality control check', '/ˈkwɒlɪti kənˈtroʊl tʃek/', 'noun', '{"zh-TW":["品質管制檢查"],"en":["an inspection to verify that a product meets quality specifications"]}', NULL, 'conduct a quality control check / fail a quality control check', '[{"en":"Each unit undergoes a quality control check before shipping.","zh-TW":"每個單位在出貨前都要接受品質管制檢查。"},{"en":"The quality control check detected flaws in 2% of units.","zh-TW":"品質管制檢查發現了2%的單位存在缺陷。"}]', NULL, NULL, 5, 5353, NULL),
(5354, 'quality improvement', '/ˈkwɒlɪti ɪmˈpruːvmənt/', 'noun', '{"zh-TW":["品質改善"],"en":["efforts to enhance the quality of products, services, or processes"]}', NULL, 'drive quality improvement / quality improvement initiative', '[{"en":"The quality improvement program reduced defect rates by half.","zh-TW":"品質改善計劃將缺陷率降低了一半。"},{"en":"Continuous quality improvement is a key principle of lean manufacturing.","zh-TW":"持續品質改善是精益製造的關鍵原則。"}]', NULL, NULL, 5, 5354, NULL),
(5355, 'quality standard', '/ˈkwɒlɪti ˈstændərd/', 'noun', '{"zh-TW":["品質標準"],"en":["a specification defining the required level of quality for products or processes"]}', NULL, 'meet quality standards / quality standard certification', '[{"en":"All products must meet the ISO quality standard before shipment.","zh-TW":"所有產品在發貨前必須符合ISO品質標準。"},{"en":"Setting clear quality standards reduces defects and customer complaints.","zh-TW":"設定清晰的品質標準減少了缺陷和客戶投訴。"}]', NULL, NULL, 5, 5355, NULL),
(5356, 'quantify', '/ˈkwɒntɪfaɪ/', 'verb', '{"zh-TW":["量化；計量"],"en":["to express or measure something in numerical terms"]}', NULL, 'quantify risk / quantify the impact / quantify savings', '[{"en":"The report quantified the potential savings from the initiative.","zh-TW":"報告量化了此計劃的潛在節省。"},{"en":"It is difficult to quantify the value of brand reputation.","zh-TW":"很難量化品牌聲譽的價值。"}]', '{"noun":"quantification","adjective":"quantified"}', NULL, 3, 5356, NULL),
(5357, 'quantitative analysis', '/ˌkwɒntɪˈteɪtɪv əˈnæləsɪs/', 'noun', '{"zh-TW":["定量分析"],"en":["analysis based on measurable data and statistical methods"]}', NULL, 'conduct quantitative analysis / use quantitative analysis', '[{"en":"Quantitative analysis confirmed the positive correlation between ad spend and sales.","zh-TW":"定量分析確認了廣告支出和銷售之間的正相關關係。"},{"en":"Fund managers use quantitative analysis to identify trading opportunities.","zh-TW":"基金管理人使用定量分析識別交易機會。"}]', NULL, NULL, 5, 5357, NULL),
(5358, 'quantitative easing', '/ˈkwɒntɪtətɪv ˈiːzɪŋ/', 'noun', '{"zh-TW":["量化寬鬆"],"en":["a monetary policy tool involving large-scale asset purchases by central banks"]}', NULL, 'implement quantitative easing / quantitative easing program / end quantitative easing', '[{"en":"The central bank launched quantitative easing to stimulate the economy.","zh-TW":"中央銀行啟動量化寬鬆以刺激經濟。"},{"en":"Critics argue that quantitative easing widened wealth inequality.","zh-TW":"批評者認為量化寬鬆擴大了財富不平等。"}]', NULL, NULL, 5, 5358, NULL),
(5359, 'quantitative tightening', '/ˈkwɒntɪtətɪv ˈtaɪtənɪŋ/', 'noun', '{"zh-TW":["量化緊縮"],"en":["a monetary policy tool where a central bank reduces its asset holdings to decrease money supply"]}', NULL, 'implement quantitative tightening / quantitative tightening program / reverse of quantitative easing', '[{"en":"Quantitative tightening reverses asset purchases made during quantitative easing.","zh-TW":"量化緊縮逆轉了量化寬鬆期間進行的資產購買。"},{"en":"Quantitative tightening raises long-term interest rates by reducing central bank bond holdings.","zh-TW":"量化緊縮通過減少中央銀行的債券持有量，提高了長期利率。"}]', NULL, NULL, 5, 5359, NULL),
(5360, 'quantity', '/ˈkwɒntɪti/', 'noun', '{"zh-TW":["數量"],"en":["an amount or number"]}', '{"root":{"text":"quant","meaning":"how much (多少)"},"suffix":{"text":"-ity","meaning":"狀態"}}', 'large quantity / in quantity / quantity discount', '[{"en":"We ordered a large quantity of supplies.","zh-TW":"我們訂購了大量物資。"},{"en":"Discounts are available for purchases in quantity.","zh-TW":"大量購買可享折扣。"}]', '{"adjective":"quantitative","verb":"quantify"}', NULL, 3, 5360, NULL),
(5361, 'quantum computing', '/ˈkwɒntəm kəmˈpjuːtɪŋ/', 'noun', '{"zh-TW":["量子計算"],"en":["computing using quantum-mechanical phenomena such as superposition and entanglement"]}', NULL, 'quantum computing research / quantum computing applications / quantum computing advantage', '[{"en":"Quantum computing could solve optimization problems that are impossible for classical computers.","zh-TW":"量子計算可以解決傳統計算機無法解決的優化問題。"},{"en":"Tech giants are investing heavily in quantum computing research.","zh-TW":"科技巨頭正在大力投資量子計算研究。"}]', NULL, NULL, 5, 5361, NULL),
(5362, 'quarter', '/ˈkwɔːrtər/', 'noun', '{"zh-TW":["季度","四分之一"],"en":["a period of three months","one-fourth"]}', '{"root":{"text":"quart","meaning":"fourth (第四)"}}', 'first quarter / quarterly report / quarter of the year', '[{"en":"Sales increased by 5% in the third quarter.","zh-TW":"第三季度銷售增長了5%。"},{"en":"A quarter of employees work remotely.","zh-TW":"四分之一的員工遠程工作。"}]', '{"adjective":"quarterly","adverb":"quarterly"}', NULL, 3, 5362, NULL),
(5363, 'quarterly', '/ˈkwɔːrtərli/', 'adjective', '{"zh-TW":["每季的；季度的"],"en":["occurring four times a year"]}', NULL, 'quarterly meeting / quarterly review', '[{"en":"The company holds quarterly meetings to review progress.","zh-TW":"公司每季度舉行會議以審查進展。"},{"en":"A quarterly review helps identify issues early.","zh-TW":"季度審查有助於及早發現問題。"}]', '{"adverb":"quarterly","noun":"quarter"}', NULL, 3, 5363, 430),
(5364, 'quarterly earnings', '/ˈkwɔːrtərli ˈɜːrnɪŋz/', 'noun', '{"zh-TW":["季度盈利；季報"],"en":["the profit or revenue reported every three months"]}', NULL, 'report quarterly earnings / strong quarterly earnings', '[{"en":"Quarterly earnings exceeded analyst expectations by 15%.","zh-TW":"季度盈利超出分析師預期15%。"},{"en":"Investors closely watch quarterly earnings reports for growth signals.","zh-TW":"投資者密切關注季度盈利報告以尋找增長信號。"}]', NULL, NULL, 5, 5364, NULL),
(5365, 'quarterly report', '/ˈkwɔːrtərli rɪˈpɔːrt/', 'noun', '{"zh-TW":["季報；季度財務報告"],"en":["a financial report published every three months"]}', NULL, 'release a quarterly report / quarterly report earnings / quarterly report guidance', '[{"en":"The quarterly report beat analyst expectations by 15%.","zh-TW":"季報超出分析師預期15%。"},{"en":"Investors analyze quarterly reports to track company performance.","zh-TW":"投資者分析季報以追蹤公司績效。"}]', '{"abbreviation":"10-Q (US)"}', NULL, 5, 5365, NULL),
(5366, 'quarterly review', '/ˈkwɔːrtərli rɪˈvjuː/', 'noun', '{"zh-TW":["季度審查；季評"],"en":["a formal evaluation of business performance every three months"]}', NULL, 'conduct a quarterly review / quarterly review meeting / quarterly review results', '[{"en":"The quarterly review showed all KPIs were on track.","zh-TW":"季度審查顯示所有關鍵績效指標都在正軌上。"},{"en":"Leadership presents the quarterly review to the board each quarter.","zh-TW":"領導層每季向董事會呈報季度審查。"}]', NULL, NULL, 5, 5366, NULL),
(5367, 'query', '/ˈkwɪri/', 'noun', '{"zh-TW":["查詢；疑問"],"en":["a question; a request for information"]}', '{"root":{"text":"quer","meaning":"ask (問)"}}', 'raise a query / answer queries / database query', '[{"en":"Please direct any queries to customer service.","zh-TW":"請將任何疑問轉至客服。"},{"en":"We received numerous queries about the product.","zh-TW":"我們收到大量關於產品的查詢。"}]', '{"verb":"query"}', NULL, 2, 5367, NULL),
(5368, 'question', '/ˈkwɛstʃən/', 'noun', '{"zh-TW":["問題；疑問"],"en":["a sentence asking for information"]}', NULL, 'ask a question / out of the question', '[{"en":"Do you have any questions?","zh-TW":"你有什麼問題嗎？"},{"en":"A pay cut is out of the question.","zh-TW":"減薪是不可能的。"}]', '{"noun":"question","verb":"question","adjective":"questionable","noun2":"questionnaire"}', NULL, 3, 5368, NULL),
(5369, 'questionnaire', '/ˌkwɛstʃəˈnɛr/', 'noun', '{"zh-TW":["問卷"],"en":["a set of written questions for a survey"]}', '{"root":{"text":"question","meaning":"question (問題)"},"suffix":{"text":"-naire","meaning":"名詞後綴"}}', 'fill out a questionnaire / distribute a questionnaire', '[{"en":"Please complete the customer satisfaction questionnaire.","zh-TW":"請填寫客戶滿意度問卷。"},{"en":"The questionnaire was distributed to all staff.","zh-TW":"問卷已分發給所有員工。"}]', NULL, NULL, 5, 5369, NULL),
(5370, 'queue', '/kjuː/', 'noun', '{"zh-TW":["隊伍；排隊"],"en":["a line of people waiting for something"]}', '{"root":{"text":"queue","meaning":"tail (尾巴)"},"logic":"源自法語 queue（尾巴），人排成一列如尾巴。"}', 'join the queue / queue up', '[{"en":"There was a long queue at the checkout.","zh-TW":"結帳處排了很長的隊伍。"},{"en":"Please queue up and wait for your turn.","zh-TW":"請排隊等候。"}]', '{"verb":"queue"}', NULL, 2, 5370, 915),
(5371, 'quick', '/kwɪk/', 'adjective', '{"zh-TW":["快速的"],"en":["moving fast; done in a short time"]}', NULL, 'quick response / quick fix', '[{"en":"Thank you for your quick response.","zh-TW":"感謝你的快速回覆。"},{"en":"There is no quick fix for this issue.","zh-TW":"這個問題沒有速效解決辦法。"}]', '{"adjective":"quick","adverb":"quickly","verb":"quicken"}', NULL, 2, 5371, NULL),
(5372, 'quick ratio', '/kwɪk ˈreɪʃioʊ/', 'noun', '{"zh-TW":["速動比率；速動比"],"en":["current assets minus inventory divided by current liabilities"]}', NULL, 'calculate quick ratio / maintain quick ratio', '[{"en":"A quick ratio above 1 indicates the company can meet short-term obligations.","zh-TW":"速動比率高於1表明公司可以履行短期義務。"},{"en":"The quick ratio declined after large inventory buildup.","zh-TW":"大量庫存積累後，速動比率下降了。"}]', '{"alternative":"acid test ratio"}', NULL, 4, 5372, NULL),
(5373, 'quiet', '/ˈkwaɪət/', 'adjective', '{"zh-TW":["安靜的"],"en":["making little noise"]}', NULL, 'keep quiet / quiet period', '[{"en":"Please keep quiet in the library area.","zh-TW":"請在圖書區保持安靜。"},{"en":"January is usually a quiet period for sales.","zh-TW":"一月通常是銷售淡季。"}]', '{"adjective":"quiet","noun":"quiet","adverb":"quietly","verb":"quiet"}', NULL, 2, 5373, NULL),
(5374, 'quorum', '/ˈkwɔːrəm/', 'noun', '{"zh-TW":["法定人數；法定出席人數"],"en":["the minimum number of members needed to conduct valid business at a meeting"]}', NULL, 'reach a quorum / quorum requirement / lack of quorum', '[{"en":"The meeting was postponed because a quorum was not present.","zh-TW":"由於未達到法定人數，會議被推遲了。"},{"en":"The bylaws require a quorum of 50% for major decisions.","zh-TW":"章程要求重要決策需要50%的法定出席人數。"}]', NULL, NULL, 2, 5374, NULL),
(5375, 'quota', '/ˈkwoʊtə/', 'noun', '{"zh-TW":["配額；限額"],"en":["a limited amount that is allowed"]}', '{"root":{"text":"quot","meaning":"how many (多少)"}}', 'sales quota / meet the quota / import quota', '[{"en":"Each salesperson has a monthly quota.","zh-TW":"每位銷售人員有月度配額。"},{"en":"The import quota has been reached.","zh-TW":"進口配額已達到。"}]', NULL, NULL, 2, 5375, 431),
(5376, 'quota system', '/ˈkwoʊtə ˈsɪstəm/', 'noun', '{"zh-TW":["配額制度"],"en":["a system that limits the quantity of goods imported or produced"]}', NULL, 'implement a quota system / quota system restriction', '[{"en":"The government introduced a quota system to limit textile imports.","zh-TW":"政府引入了配額制度以限制紡織品進口。"},{"en":"A quota system helps protect domestic industries from foreign competition.","zh-TW":"配額制度有助於保護國內產業免受外國競爭。"}]', NULL, NULL, 4, 5376, NULL),
(5377, 'quote', '/kwoʊt/', 'verb', '{"zh-TW":["報價；引用","引用；報價"],"en":["to state a price; to repeat someone''s words","to repeat words; to state a price"]}', '{"root":{"text":"quot","meaning":"how many (多少)"}}', 'quote a price / get a quote / quote from; quote a price / get a quote / as quoted', '[{"en":"They quoted us a price of $5,000.","zh-TW":"他們報價五千美元。"},{"en":"Please quote the reference number in your reply.","zh-TW":"回覆時請引用參考編號。"},{"en":"Can you quote me a price for 1000 units?","zh-TW":"你能報1000件的價嗎？"},{"en":"As quoted in the proposal, the cost is $50K.","zh-TW":"如提案中所報，費用為五萬美元。"}]', '{"noun":"quote, quotation"}', NULL, 2, 5377, NULL),
(5378, 'R&D', '/ˌɑːr ən ˈdiː/', 'noun', '{"zh-TW":["研發"],"en":["research and development; work aimed at creating new knowledge or products"]}', NULL, 'R&D budget / invest in R&D / R&D department', '[{"en":"The company allocates 15% of revenue to R&D.","zh-TW":"公司將15%的收入用於研發。"},{"en":"R&D investment is critical for maintaining technological leadership.","zh-TW":"研發投資對於保持技術領先地位至關重要。"}]', '{"full form":"research and development"}', NULL, 1, 5378, NULL),
(5379, 'rack', '/ræk/', 'noun', '{"zh-TW":["架子；貨架"],"en":["a frame or shelf for holding or displaying items"]}', '{"root":{"text":"rack","meaning":"frame (框架)"},"logic":"指用於放置或展示物品的架子。"}', 'clothes rack / luggage rack', '[{"en":"Put the clothes back on the rack please.","zh-TW":"請把衣服放回架子上。"},{"en":"The magazine rack is near the entrance.","zh-TW":"雜誌架在入口附近。"}]', NULL, NULL, 1, 5379, NULL),
(5380, 'rack rate', '/ræk reɪt/', 'noun', '{"zh-TW":["標準房價；公告房價"],"en":["the standard, undiscounted price of a hotel room"]}', NULL, 'rack rate / below rack rate', '[{"en":"Always negotiate below the rack rate when booking directly.","zh-TW":"直接訂房時務必嘗試低於公告房價。"},{"en":"The rack rate for the weekend is higher than usual.","zh-TW":"週末的標準房價高於平時。"}]', NULL, NULL, 3, 5380, NULL),
(5381, 'racket', '/''rækɪt/', 'noun', '{"zh-TW":["球拍"],"en":["a bat used in sports such as tennis, badminton, and squash"]}', NULL, 'tennis racket / swing a racket / high-quality racket', '[{"en":"He strung his tennis racket to the right tension for optimal performance.","zh-TW":"他將網球拍繩線調整到最佳性能的正確張力。"},{"en":"Choosing the right racket weight is crucial for preventing arm injuries.","zh-TW":"選擇正確的球拍重量對於預防手臂受傷至關重要。"}]', NULL, NULL, 2, 5381, NULL),
(5382, 'radical', '/ˈrædɪkəl/', 'adjective', '{"zh-TW":["根本的；激進的"],"en":["fundamental; favoring extreme change"]}', '{"root":{"text":"radic","meaning":"root (根)"},"suffix":{"text":"-al","meaning":"...的"}}', 'radical change / radical approach / radical reform', '[{"en":"The company underwent a radical transformation.","zh-TW":"公司經歷了根本性的轉變。"},{"en":"Radical changes are needed to fix the problem.","zh-TW":"需要根本改變來解決問題。"}]', '{"adverb":"radically","noun":"radicalism"}', NULL, 3, 5382, NULL),
(5383, 'radiology', '/ˌreɪdiˈɒlədʒi/', 'noun', '{"zh-TW":["放射科；放射學"],"en":["the branch of medicine using imaging to diagnose diseases"]}', NULL, 'radiology department / radiology report', '[{"en":"The radiology report showed a minor fracture.","zh-TW":"放射科報告顯示有輕微骨折。"},{"en":"Radiology includes X-rays, CT scans, and MRI.","zh-TW":"放射科包括X光、電腦斷層掃描和磁振造影。"}]', '{"noun":"radiologist","adjective":"radiological"}', NULL, 3, 5383, NULL),
(5384, 'rail freight', '/''reɪl freɪt/', 'noun', '{"zh-TW":["鐵路貨運"],"en":["the transportation of goods by train"]}', NULL, 'use rail freight / rail freight network / benefit of rail freight', '[{"en":"Rail freight is a cost-effective and environmentally friendly alternative to road transport.","zh-TW":"鐵路貨運是公路運輸的一種具有成本效益且環保的替代方案。"},{"en":"The company shifted to rail freight to reduce its carbon emissions.","zh-TW":"公司轉向鐵路貨運，以減少碳排放。"}]', NULL, NULL, 4, 5384, NULL),
(5385, 'rail pass', '/reɪl pæs/', 'noun', '{"zh-TW":["鐵路通票"],"en":["a pass allowing unlimited train travel for a fixed period"]}', NULL, 'buy a rail pass / Europe rail pass', '[{"en":"A Europe rail pass offers unlimited travel on most trains.","zh-TW":"歐洲鐵路通票可在大多數火車上無限次乘坐。"},{"en":"The rail pass is valid for 15 days from first use.","zh-TW":"鐵路通票從首次使用起有效15天。"}]', NULL, NULL, 3, 5385, NULL),
(5386, 'rain', '/reɪn/', 'noun', '{"zh-TW":["雨"],"en":["water falling from clouds"]}', NULL, 'rain check / rainy day', '[{"en":"Can I take a rain check on that meeting?","zh-TW":"那個會議可以改天再約嗎？"},{"en":"Save money for a rainy day.","zh-TW":"存錢以備不時之需。"}]', '{"noun":"rain","verb":"rain","adjective":"rainy"}', NULL, 1, 5386, NULL),
(5387, 'rainfall', '/ˈreɪnfɔːl/', 'noun', '{"zh-TW":["降雨量"],"en":["the amount of rain that falls in an area"]}', '{"root":{"text":"rain","meaning":"rain (雨)"},"suffix":{"text":"fall","meaning":"falling (落下)"},"logic":"雨的落下量，即「降雨量」。"}', 'average rainfall / heavy rainfall', '[{"en":"The average annual rainfall here is 800mm.","zh-TW":"這裡的年平均降雨量為800毫米。"},{"en":"Unusually heavy rainfall caused flooding.","zh-TW":"異常大量的降雨導致了洪水。"}]', NULL, NULL, 3, 5387, NULL),
(5388, 'rainwater harvesting', '/ˈreɪnwɔːtər ˈhɑːrvɪstɪŋ/', 'noun', '{"zh-TW":["雨水收集；集水"],"en":["collecting and storing rainwater for later use"]}', NULL, 'practice rainwater harvesting / rainwater harvesting system', '[{"en":"The building uses a rainwater harvesting system for irrigation.","zh-TW":"該建築使用雨水收集系統進行灌溉。"},{"en":"Rainwater harvesting reduces dependence on municipal water supplies.","zh-TW":"雨水收集減少了對市政供水的依賴。"}]', NULL, NULL, 5, 5388, NULL),
(5389, 'raise', '/reɪz/', 'verb', '{"zh-TW":["提高；籌集","提出"],"en":["to increase","to collect money","to bring up a topic"]}', NULL, 'raise awareness / raise funds / raise concerns / raise the issue', '[{"en":"The company raised prices by 10%.","zh-TW":"公司提高了10%的價格。"},{"en":"She raised an important concern at the meeting.","zh-TW":"她在會議上提出了重要的擔憂。"}]', '{"noun":"raise"}', NULL, 2, 5389, NULL),
(5390, 'raise capital', '/reɪz ˈkæpɪtl/', 'verb', '{"zh-TW":["籌集資金；融資"],"en":["to obtain money for investment or operations"]}', NULL, 'raise capital through equity / raise capital from investors', '[{"en":"The startup raised capital through three rounds of venture funding.","zh-TW":"新創公司通過三輪創業投資籌集了資金。"},{"en":"The company raised capital via a rights issue to fund the acquisition.","zh-TW":"公司通過配股籌集資金為收購提供資金。"}]', NULL, NULL, 5, 5390, NULL),
(5391, 'range', '/reɪndʒ/', 'noun', '{"zh-TW":["範圍；系列"],"en":["the extent; a variety"]}', NULL, 'a wide range of / price range / within range / range from...to', '[{"en":"We offer a wide range of services.","zh-TW":"我們提供各種各樣的服務。"},{"en":"Prices range from $10 to $100.","zh-TW":"價格從10美元到100美元不等。"}]', '{"verb":"range"}', NULL, 2, 5391, 189),
(5392, 'rank', '/ræŋk/', 'noun', '{"zh-TW":["排名；等級"],"en":["a position in a hierarchy"]}', NULL, 'rank among / top-ranked / rank first', '[{"en":"The company ranks among the top 10 globally.","zh-TW":"公司在全球排名前十。"},{"en":"She holds the rank of vice president.","zh-TW":"她擔任副總裁一職。"}]', '{"verb":"rank","noun":"ranking"}', NULL, 1, 5392, NULL),
(5393, 'rapid', '/ˈræpɪd/', 'adjective', '{"zh-TW":["快速的；迅速的"],"en":["happening in a short time"]}', '{"root":{"text":"rap","meaning":"seize quickly (快速抓取)"}}', 'rapid growth / rapid change / rapid development', '[{"en":"The industry has seen rapid growth.","zh-TW":"該行業經歷了快速增長。"},{"en":"Rapid technological advances drive innovation.","zh-TW":"快速的技術進步推動創新。"}]', '{"adverb":"rapidly","noun":"rapidity"}', NULL, 2, 5393, NULL),
(5394, 'rate', '/reɪt/', 'noun', '{"zh-TW":["比率；費率","速度"],"en":["a measured quantity; a charge"]}', NULL, 'interest rate / at a rate of / exchange rate / crime rate', '[{"en":"The interest rate has been lowered.","zh-TW":"利率已被降低。"},{"en":"At this rate, we will finish by December.","zh-TW":"以這個速度，我們將在十二月前完成。"}]', '{"verb":"rate","noun":"rating"}', NULL, 1, 5394, NULL),
(5395, 'rate card', '/reɪt kɑːrd/', 'noun', '{"zh-TW":["費率表；收費標準"],"en":["a published list of prices for advertising, consulting, or other services"]}', NULL, 'refer to the rate card / rate card pricing', '[{"en":"The media agency provided a rate card for advertising spots.","zh-TW":"媒體代理提供了廣告時段的費率表。"},{"en":"Rate card prices are the starting point for negotiation.","zh-TW":"費率表上的價格是談判的起始點。"}]', NULL, NULL, 3, 5395, NULL),
(5396, 'rate of exchange', '/reɪt əv ɪksˈtʃeɪndʒ/', 'noun', '{"zh-TW":["匯率"],"en":["the value at which one currency can be exchanged for another"]}', NULL, 'apply the current rate of exchange / rate of exchange fluctuation', '[{"en":"The company hedges against rate of exchange fluctuations.","zh-TW":"公司對沖匯率波動風險。"},{"en":"Importers must monitor the rate of exchange daily.","zh-TW":"進口商必須每日監控匯率。"}]', '{"synonym":"exchange rate"}', NULL, 5, 5396, NULL),
(5397, 'rate of return', '/reɪt əv rɪˈtɜːrn/', 'noun', '{"zh-TW":["報酬率；回報率"],"en":["the gain or loss on an investment expressed as a percentage"]}', NULL, 'calculate rate of return / target rate of return', '[{"en":"The investment achieved a rate of return of 12% per year.","zh-TW":"該投資實現了每年12%的報酬率。"},{"en":"A higher rate of return compensates for greater risk taken.","zh-TW":"更高的報酬率補償了承擔的更大風險。"}]', NULL, NULL, 5, 5397, NULL),
(5398, 'ratification', '/ˌrætɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["批准；認可"],"en":["the formal approval of an agreement by authorized parties"]}', NULL, 'ratification of a treaty / board ratification / pending ratification', '[{"en":"The merger required shareholder ratification at the AGM.","zh-TW":"合併需要在年度股東大會上獲得股東批准。"},{"en":"Ratification of the agreement was delayed by legal review.","zh-TW":"協議的批准因法律審查而延遲。"}]', '{"verb":"ratify"}', NULL, 4, 5398, NULL),
(5399, 'ratify', '/ˈrætɪfaɪ/', 'verb', '{"zh-TW":["批准；正式確認"],"en":["to formally approve and make valid, especially a treaty"]}', NULL, 'ratify a treaty / ratify an agreement / fail to ratify', '[{"en":"The senate must ratify the international climate agreement.","zh-TW":"參議院必須批准國際氣候協議。"},{"en":"The board ratified the merger after reviewing the final terms.","zh-TW":"董事會在審查最終條款後批准了合併。"}]', '{"noun":"ratification","adjective":"ratified"}', NULL, 2, 5399, NULL);
