(5400, 'ratio', '/ˈreɪʃioʊ/', 'noun', '{"zh-TW":["比率；比例"],"en":["the relationship between two numbers"]}', '{"root":{"text":"rat","meaning":"reckon (計算)"}}', 'debt-to-equity ratio / ratio of...to... / maintain a ratio', '[{"en":"The debt-to-equity ratio is 2:1.","zh-TW":"債務權益比為2:1。"},{"en":"What is the ratio of managers to employees?","zh-TW":"經理與員工的比例是多少？"}]', NULL, NULL, 2, 5400, NULL),
(5401, 'rational', '/ˈræʃənəl/', 'adjective', '{"zh-TW":["理性的；合理的"],"en":["based on reason; logical"]}', '{"root":{"text":"ration","meaning":"reason (理性)"},"suffix":{"text":"-al","meaning":"...的"}}', 'rational decision / rational thinking / rational approach', '[{"en":"We need to make a rational decision.","zh-TW":"我們需要做出理性決定。"},{"en":"His approach was entirely rational.","zh-TW":"他的方法完全合理。"}]', '{"noun":"rationality, rationale","adverb":"rationally","verb":"rationalize"}', NULL, 3, 5401, NULL),
(5402, 'rational choice theory', '/ˈræʃənəl tʃɔɪs ˈθɪəri/', 'noun', '{"zh-TW":["理性選擇理論"],"en":["a framework assuming individuals make decisions to maximize utility"]}', NULL, 'apply rational choice theory / rational choice theory model / critique of rational choice theory', '[{"en":"Rational choice theory predicts that voters will support policies that benefit them.","zh-TW":"理性選擇理論預測選民將支持對其有利的政策。"},{"en":"Behavioral economics challenges rational choice theory by documenting cognitive biases.","zh-TW":"行為經濟學通過記錄認知偏見來挑戰理性選擇理論。"}]', NULL, NULL, 5, 5402, NULL),
(5403, 'rationale', '/ˌræʃəˈnɑːl/', 'noun', '{"zh-TW":["基本原理；理由"],"en":["the underlying reasons for a decision or action"]}', NULL, 'provide a rationale / explain the rationale', '[{"en":"Please provide the rationale for this budget request.","zh-TW":"請提供此預算申請的理由。"},{"en":"The rationale behind the restructuring was to improve efficiency.","zh-TW":"重組背後的基本原理是提高效率。"}]', NULL, NULL, 3, 5403, NULL),
(5404, 'rationalize', '/ˈræʃənəlaɪz/', 'verb', '{"zh-TW":["合理化；使合理"],"en":["to attempt to explain or justify behavior with logical reasons"]}', NULL, 'rationalize a decision / rationalize costs / rationalize behavior', '[{"en":"He rationalized his poor performance by blaming external factors.","zh-TW":"他通過怪罪外部因素來合理化自己的糟糕表現。"},{"en":"Companies rationalize their operations to improve efficiency.","zh-TW":"公司對運作進行合理化以提高效率。"}]', '{"noun":"rationalization","adjective":"rational"}', NULL, 4, 5404, NULL),
(5405, 'raw', '/rɔː/', 'adjective', '{"zh-TW":["原始的；未加工的"],"en":["not processed; in natural state"]}', NULL, 'raw materials / raw data / raw talent', '[{"en":"The cost of raw materials has increased.","zh-TW":"原材料成本已增加。"},{"en":"We need to analyze the raw data.","zh-TW":"我們需要分析原始數據。"}]', NULL, NULL, 1, 5405, NULL),
(5406, 'reach', '/riːtʃ/', 'verb', '{"zh-TW":["到達；達到"],"en":["to arrive at","to achieve"]}', NULL, 'reach an agreement / reach out', '[{"en":"We reached an agreement after long talks.","zh-TW":"經過長時間談判我們達成了協議。"},{"en":"Feel free to reach out anytime.","zh-TW":"隨時可以聯繫我們。"}]', '{"verb":"reach","noun":"reach"}', NULL, 2, 5406, NULL),
(5407, 'react', '/riˈækt/', 'verb', '{"zh-TW":["反應；回應"],"en":["to respond to something"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"act","meaning":"do (做)"}}', 'react to / react quickly / react negatively', '[{"en":"How did the market react to the news?","zh-TW":"市場對這消息如何反應？"},{"en":"She reacted quickly to the crisis.","zh-TW":"她對危機迅速做出反應。"}]', '{"noun":"reaction","adjective":"reactive"}', NULL, 2, 5407, NULL),
(5408, 'read', '/riːd/', 'verb', '{"zh-TW":["閱讀"],"en":["to look at and understand written words"]}', NULL, 'read carefully / well-read', '[{"en":"Please read the contract carefully.","zh-TW":"請仔細閱讀合約。"},{"en":"She is well-read in business literature.","zh-TW":"她廣泛閱讀商業文獻。"}]', '{"verb":"read","noun":"reader","noun2":"reading","adjective":"readable"}', NULL, 1, 5408, NULL),
(5409, 'readership', '/ˈriːdərʃɪp/', 'noun', '{"zh-TW":["讀者群；讀者人數"],"en":["the readers of a newspaper, magazine, or book collectively"]}', NULL, 'target readership / expand readership / loyal readership', '[{"en":"The magazine grew its readership through digital subscriptions.","zh-TW":"該雜誌通過數字訂閱擴大了讀者群。"},{"en":"A broad readership indicates a publication''s cultural influence.","zh-TW":"廣泛的讀者群表明出版物的文化影響力。"}]', NULL, NULL, 4, 5409, NULL),
(5410, 'reading comprehension', '/''riːdɪŋ ˌkɒmprɪˈhenʃən/', 'noun', '{"zh-TW":["閱讀理解"],"en":["the ability to understand and interpret written text"]}', NULL, 'improve reading comprehension / reading comprehension test / develop reading comprehension', '[{"en":"Reading comprehension is a fundamental skill assessed in most standardized tests.","zh-TW":"閱讀理解是大多數標準化測驗中評估的基本技能。"},{"en":"She practiced reading comprehension by summarizing each paragraph she read.","zh-TW":"她通過概括所讀的每個段落來練習閱讀理解。"}]', NULL, NULL, 5, 5410, NULL),
(5411, 'ready', '/ˈrɛdi/', 'adjective', '{"zh-TW":["準備好的"],"en":["prepared for action"]}', NULL, 'get ready / ready-made', '[{"en":"Are you ready for the presentation?","zh-TW":"你準備好報告了嗎？"},{"en":"We offer ready-made solutions.","zh-TW":"我們提供現成的解決方案。"}]', '{"adjective":"ready","noun":"readiness","verb":"ready"}', NULL, 2, 5411, NULL),
(5412, 'real', '/riːl/', 'adjective', '{"zh-TW":["真實的；實際的"],"en":["actually existing","genuine"]}', NULL, 'real estate / in real time', '[{"en":"She works in real estate.","zh-TW":"她從事房地產業。"},{"en":"We track data in real time.","zh-TW":"我們即時追蹤數據。"}]', '{"adjective":"real","noun":"reality","adverb":"really","adjective2":"realistic","verb":"realize"}', NULL, 1, 5412, NULL),
(5413, 'real assets', '/rɪəl ˈæsets/', 'noun', '{"zh-TW":["實物資產"],"en":["tangible assets with intrinsic value such as real estate, land, or commodities"]}', NULL, 'invest in real assets / real assets allocation / real assets portfolio', '[{"en":"Real assets provide inflation protection for long-term investors.","zh-TW":"實物資產為長期投資者提供通膨保護。"},{"en":"Pension funds allocate to real assets for stable, inflation-linked returns.","zh-TW":"養老基金配置實物資產以獲得穩定的通膨掛鉤回報。"}]', NULL, NULL, 4, 5413, NULL),
(5414, 'real estate', '/ˈrɪəl ɪˈsteɪt/', 'noun', '{"zh-TW":["房地產；不動產"],"en":["property consisting of land and buildings"]}', NULL, 'invest in real estate / commercial real estate', '[{"en":"Commercial real estate prices fell during the economic downturn.","zh-TW":"商業房地產價格在經濟低迷期間下跌了。"},{"en":"The company''s real estate portfolio includes offices in five cities.","zh-TW":"公司的房地產投資組合包括五個城市的辦公室。"}]', NULL, NULL, 4, 5414, NULL),
(5415, 'real estate agent', '/ˌrɪəl ɪˈsteɪt ˈeɪdʒənt/', 'noun', '{"zh-TW":["房地產經紀人"],"en":["a person who arranges the buying and selling of property"]}', NULL, 'hire a real estate agent / trusted real estate agent', '[{"en":"A real estate agent helped them find their dream home.","zh-TW":"房地產經紀人幫助他們找到了夢想中的家。"},{"en":"Choose a real estate agent with knowledge of the local market.","zh-TW":"選擇熟悉當地市場的房地產經紀人。"}]', NULL, NULL, 5, 5415, NULL),
(5416, 'real estate bubble', '/''riəl ɪˌsteɪt ˌbʌbəl/', 'noun', '{"zh-TW":["房地產泡沫"],"en":["a rapid increase in the value of real estate driven by speculation, often followed by a sharp decline"]}', NULL, 'real estate bubble burst / prevent a real estate bubble / recognize a real estate bubble', '[{"en":"Economists warned of a potential real estate bubble driven by speculative investment.","zh-TW":"經濟學家警告稱，投機性投資可能推動房地產泡沫的形成。"},{"en":"When the real estate bubble burst, many homeowners found themselves owing more than their homes were worth.","zh-TW":"當房地產泡沫破裂時，許多房主發現自己的欠款超過了房屋的價值。"}]', '{"noun":"bubble"}', NULL, 5, 5416, NULL),
(5417, 'real estate investment', '/''riəl ɪˌsteɪt ɪnˌvestmənt/', 'noun', '{"zh-TW":["房地產投資"],"en":["the purchase of property as a strategy to generate income or profit"]}', NULL, 'make a real estate investment / real estate investment trust / benefit of real estate investment', '[{"en":"Real estate investment is considered one of the most stable forms of wealth building.","zh-TW":"房地產投資被認為是最穩定的財富積累方式之一。"},{"en":"She diversified her portfolio by adding real estate investment to her financial strategy.","zh-TW":"她通過在財務策略中增加房地產投資來多元化其投資組合。"}]', '{"adjective":"real-estate","noun":"real estate investor"}', NULL, 5, 5417, NULL),
(5418, 'real estate investment trust', '/riːl ɪˈsteɪt ɪnˈvestmənt trʌst/', 'noun', '{"zh-TW":["不動產投資信託"],"en":["a company owning income-producing real estate that is publicly traded"]}', NULL, 'invest in a REIT / commercial REIT / residential REIT', '[{"en":"The REIT pays quarterly dividends from rental income.","zh-TW":"不動產投資信託從租金收入中每季支付股利。"},{"en":"REITs allow small investors to access commercial property markets.","zh-TW":"不動產投資信託允許小投資者進入商業地產市場。"}]', '{"abbreviation":"REIT"}', NULL, 5, 5418, NULL),
(5419, 'real-time data', '/ˌriːəl taɪm ˈdeɪtə/', 'noun', '{"zh-TW":["即時數據；實時數據"],"en":["information processed and available instantly as events occur"]}', NULL, 'access real-time data / real-time data dashboard', '[{"en":"The operations team uses real-time data to monitor production lines.","zh-TW":"運營團隊使用實時數據監控生產線。"},{"en":"Real-time data enables faster and more accurate business decisions.","zh-TW":"實時數據使業務決策更快更準確。"}]', NULL, NULL, 5, 5419, NULL),
(5420, 'realistic', 'rɪəˈlɪstɪk', 'adjective', '{"zh-TW":["現實的；實際的","可行的"],"en":["sensible and practical","based on reality"]}', NULL, 'realistic goal/realistic expectation', '[{"en":"Set realistic goals for the team.","zh-TW":"為團隊設定現實目標。"}]', '{"noun":"realism","adverb":"realistically"}', NULL, 3, 5420, NULL),
(5421, 'realize', '/ˈriːəlaɪz/', 'verb', '{"zh-TW":["【主要意義-動詞】意識到；理解","【次要意義-動詞】獲得（利潤）；實現（資產變現）","【次要意義-動詞】實現；成就（計劃）"],"en":["[primary] to become aware of a fact or situation","[secondary] to make a profit from selling assets; to convert assets to cash","[secondary] to achieve something that was planned"]}', '{"root":{"text":"real","meaning":"real (真實)"},"suffix":{"text":"-ize","meaning":"使...化"}}', 'realize a profit / realize assets / realize a goal / realize potential', '[{"en":"The company realized a substantial profit from the sale of its subsidiary.","zh-TW":"公司從出售子公司中獲得了可觀的利潤。"},{"en":"The new plan will help the organization realize its long-term strategic goals.","zh-TW":"新計劃將幫助組織實現其長期戰略目標。"},{"en":"Investors realized gains when the stock price hit a record high.","zh-TW":"當股價創下歷史新高時，投資者實現了收益。"}]', '{"noun":"realization"}', 'realize a profit/gain = 「實現（獲得）利潤/收益」是 TOEIC 財務文章的高頻表達，realize a goal = 「實現目標」也常見，考生常誤以為 realize 只有「意識到」的意思。', 3, 5421, NULL),
(5422, 'reallocation', '/ˌriːˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["重新分配；再分配"],"en":["the redistribution of resources, funds, or personnel to a different use"]}', NULL, 'budget reallocation / resource reallocation / labor reallocation', '[{"en":"Budget reallocation shifted funds from defense to social programs.","zh-TW":"預算重新分配將資金從國防轉移到社會計畫。"},{"en":"Economic shocks often require reallocation of labor across industries.","zh-TW":"經濟衝擊通常需要跨行業重新分配勞動力。"}]', '{"verb":"reallocate","adjective":"reallocated"}', NULL, 4, 5422, NULL),
(5423, 'reason', '/ˈriːzən/', 'noun', '{"zh-TW":["原因；理由"],"en":["the cause or explanation for something"]}', NULL, 'for this reason / the reason why / reason for / reasonable', '[{"en":"For this reason, we decided to postpone.","zh-TW":"基於這個原因，我們決定延期。"},{"en":"What is the reason for the delay?","zh-TW":"延遲的原因是什麼？"}]', '{"adjective":"reasonable","adverb":"reasonably","verb":"reason"}', NULL, 2, 5423, NULL),
(5424, 'reasonable', '/ˈriːzənəbl/', 'adjective', '{"zh-TW":["合理的；適當的"],"en":["fair; sensible; not too expensive"]}', '{"root":{"text":"reason","meaning":"reason (理由)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'reasonable price / reasonable request / within a reasonable time', '[{"en":"The price seems reasonable for the quality.","zh-TW":"就品質而言價格合理。"},{"en":"Please respond within a reasonable timeframe.","zh-TW":"請在合理時間內回覆。"}]', '{"adverb":"reasonably","noun":"reasonableness"}', NULL, 4, 5424, NULL),
(5425, 'rebalancing', '/riːˈbælənsɪŋ/', 'noun', '{"zh-TW":["重新平衡；再平衡"],"en":["restoring a portfolio or system to its intended state"]}', NULL, 'portfolio rebalancing / economic rebalancing / trigger rebalancing', '[{"en":"Annual rebalancing keeps an investment portfolio aligned with its target allocation.","zh-TW":"年度再平衡使投資組合與其目標配置保持一致。"},{"en":"China''s economic rebalancing shifted focus from exports to domestic consumption.","zh-TW":"中國的經濟再平衡將重心從出口轉向內需消費。"}]', '{"verb":"rebalance","adjective":"rebalanced"}', NULL, 4, 5425, NULL),
(5426, 'rebate', '/ˈriːbeɪt/', 'noun', '{"zh-TW":["回扣；折讓"],"en":["a partial refund or discount given after a purchase"]}', NULL, 'offer a rebate / volume rebate / claim a rebate / rebate program', '[{"en":"The manufacturer offered a $50 rebate on purchases over $200.","zh-TW":"製造商對超過200美元的購買提供50美元的回扣。"},{"en":"Volume rebates incentivize customers to buy in larger quantities.","zh-TW":"數量折讓激勵客戶以更大的數量購買。"}]', '{"verb":"rebate"}', NULL, 2, 5426, NULL),
(5427, 'rebranding', '/riːˈbrændɪŋ/', 'noun', '{"zh-TW":["重新品牌化；品牌重塑"],"en":["changing the brand identity of an existing company or product"]}', NULL, 'undergo rebranding / rebranding campaign / successful rebranding', '[{"en":"The rebranding campaign refreshed the company''s outdated image.","zh-TW":"重新品牌化活動更新了公司過時的形象。"},{"en":"Rebranding was necessary after the merger to unify identities.","zh-TW":"合併後需要重新品牌化以統一品牌形象。"}]', '{"verb":"rebrand"}', NULL, 4, 5427, NULL),
(5428, 'recalibrate', '/''riːˌkælɪbreɪt/', 'verb', '{"zh-TW":["重新校準；調整方向"],"en":["to calibrate again; to adjust or change to meet new conditions or requirements"]}', NULL, 'recalibrate the strategy / recalibrate expectations / recalibrate approach', '[{"en":"After the market changed, the team needed to recalibrate their sales strategy.","zh-TW":"市場改變後，團隊需要重新校準他們的銷售策略。"},{"en":"The project manager recalibrated the timeline after receiving new information.","zh-TW":"項目經理在收到新信息後重新調整了時間表。"}]', '{"noun":"recalibration"}', NULL, 4, 5428, NULL),
(5429, 'recapitalize', '/riːˈkæpɪtəlaɪz/', 'verb', '{"zh-TW":["重新資本化；重組資本結構"],"en":["to change the capital structure of a company"]}', NULL, 'recapitalize a bank / recapitalize the business / recapitalize the balance sheet', '[{"en":"The government recapitalized the struggling bank to prevent collapse.","zh-TW":"政府重新資本化了掙扎中的銀行以防止崩潰。"},{"en":"The firm recapitalized by issuing new shares and retiring old debt.","zh-TW":"公司通過發行新股和退休舊債進行了重新資本化。"}]', '{"noun":"recapitalization","adjective":"recapitalized"}', NULL, 4, 5429, NULL),
(5430, 'receipt', '/rɪˈsiːt/', 'noun', '{"zh-TW":["收據","收據；收到"],"en":["a written acknowledgment of payment","a written proof of payment"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ceipt","meaning":"take (拿取)"},"logic":"拿回的證明，即「收據」。"}', 'keep the receipt / receipt printer; keep the receipt / upon receipt of / acknowledge receipt', '[{"en":"Please keep your receipt for returns.","zh-TW":"請保留收據以便退貨。"},{"en":"The receipt shows the date of purchase.","zh-TW":"收據上顯示購買日期。"},{"en":"Upon receipt of your payment, we will ship the order.","zh-TW":"收到付款後我們將發貨。"}]', NULL, NULL, 3, 5430, 190),
(5431, 'receivable', '/rɪˈsiːvəbəl/', 'noun', '{"zh-TW":["應收帳款"],"en":["money owed to a business by its customers"]}', NULL, 'accounts receivable / collect receivables', '[{"en":"Accounts receivable totaled $3 million.","zh-TW":"應收帳款總計300萬美元。"},{"en":"We need to collect outstanding receivables.","zh-TW":"我們需要收取未結應收帳款。"}]', '{"noun":"receivable","adjective":"receivable","verb":"receive"}', NULL, 4, 5431, 917),
(5432, 'receivables', '/rɪˈsiːvəbəlz/', 'noun', '{"zh-TW":["應收帳款"],"en":["amounts owed to a company for goods or services already delivered"]}', NULL, 'collect receivables / days receivables outstanding', '[{"en":"The company improved cash flow by accelerating collection of receivables.","zh-TW":"公司通過加速應收帳款的收款改善了現金流。"},{"en":"Factoring receivables provides immediate liquidity.","zh-TW":"應收帳款保理提供了即時流動性。"}]', NULL, NULL, 4, 5432, NULL),
(5433, 'receivables management', '/rɪˈsiːvəblz ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["應收帳款管理"],"en":["the process of monitoring and collecting amounts owed to a business"]}', NULL, 'improve receivables management / receivables management system', '[{"en":"Effective receivables management reduces the risk of bad debts.","zh-TW":"有效的應收帳款管理降低了壞帳風險。"},{"en":"The finance team implemented a receivables management policy.","zh-TW":"財務團隊實施了應收帳款管理政策。"}]', NULL, NULL, 5, 5433, NULL),
(5434, 'receivables turnover', '/rɪˈsiːvəbəlz ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["應收帳款週轉率"],"en":["a ratio measuring how quickly a company collects payments owed to it"]}', NULL, 'improve receivables turnover / calculate receivables turnover', '[{"en":"A high receivables turnover ratio indicates efficient collections.","zh-TW":"高應收帳款週轉率表明收款效率高。"},{"en":"The receivables turnover improved after stricter credit terms were enforced.","zh-TW":"在實施更嚴格的信用條款後，應收帳款週轉率有所改善。"}]', NULL, NULL, 5, 5434, NULL),
(5435, 'receive', '/rɪˈsiːv/', 'verb', '{"zh-TW":["收到；接受"],"en":["to get something that is sent or given"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"ceive","meaning":"take (拿取)"}}', 'receive a letter / receive feedback / receive approval', '[{"en":"We received your application yesterday.","zh-TW":"我們昨天收到了你的申請。"},{"en":"The project received full approval.","zh-TW":"項目獲得了全面批准。"}]', '{"noun":"receipt, receiver, reception","adjective":"receivable"}', NULL, 3, 5435, 191),
(5436, 'receivership', '/rɪˈsiːvərʃɪp/', 'noun', '{"zh-TW":["接管；破產接管"],"en":["a legal process in which a receiver takes control of a company to manage its assets"]}', NULL, 'enter receivership / company in receivership', '[{"en":"The failing company was placed into receivership by the courts.","zh-TW":"法院將破產公司置於接管之下。"},{"en":"A receivership aims to repay creditors by managing and selling assets.","zh-TW":"接管旨在通過管理和出售資產來償還債權人。"}]', NULL, NULL, 4, 5436, NULL),
(5437, 'receiving', '/rɪˈsiːvɪŋ/', 'noun', '{"zh-TW":["收貨；驗收"],"en":["the process of accepting and inspecting incoming goods at a warehouse"]}', NULL, 'receiving department / receiving dock / receiving process', '[{"en":"All incoming goods go through the receiving department first.","zh-TW":"所有進貨先經過收貨部門處理。"},{"en":"The receiving team inspects shipments against purchase orders.","zh-TW":"收貨團隊根據採購訂單核查貨物。"}]', '{"verb":"receive","noun":"receiver"}', NULL, 3, 5437, NULL),
(5438, 'recent', '/ˈriːsənt/', 'adjective', '{"zh-TW":["最近的；近來的"],"en":["happening a short time ago"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cent","meaning":"new (新)"}}', 'in recent years / recent developments / most recent', '[{"en":"In recent years, the company has expanded rapidly.","zh-TW":"近年來公司快速擴張。"},{"en":"What are the most recent developments?","zh-TW":"最新的進展是什麼？"}]', '{"adverb":"recently"}', NULL, 2, 5438, NULL),
(5439, 'reception', '/rɪˈsɛpʃən/', 'noun', '{"zh-TW":["接待處；大廳"],"en":["the area of a hotel where guests are welcomed"]}', NULL, 'hotel reception / check in at reception', '[{"en":"Please ask at reception for any assistance.","zh-TW":"如需任何協助，請向接待處詢問。"},{"en":"Reception will hold your luggage until check-in time.","zh-TW":"接待處將為您保管行李直到入住時間。"}]', '{"verb":"receive","adjective":"receptive"}', NULL, 3, 5439, NULL),
(5440, 'recession', '/rɪˈseʃən/', 'noun', '{"zh-TW":["經濟衰退"],"en":["a significant decline in economic activity lasting more than two quarters"]}', NULL, 'economic recession / survive a recession / enter a recession / recession-proof', '[{"en":"The company survived the recession by cutting costs aggressively.","zh-TW":"公司通過積極削減成本度過了經濟衰退。"},{"en":"A recession typically leads to reduced consumer spending.","zh-TW":"經濟衰退通常導致消費者支出減少。"}]', '{"adjective":"recessionary"}', NULL, 3, 5440, NULL),
(5441, 'recidivism', '/rɪˈsɪdɪvɪzəm/', 'noun', '{"zh-TW":["累犯；再犯"],"en":["the tendency to relapse into criminal behavior after punishment"]}', NULL, 'reduce recidivism / high recidivism rate / recidivism prevention', '[{"en":"Rehabilitation programs help reduce recidivism by addressing the root causes of crime.","zh-TW":"康復計畫有助於通過解決犯罪根本原因來減少累犯。"},{"en":"The prison system''s high recidivism rate raised questions about its effectiveness.","zh-TW":"監獄系統的高累犯率引發了對其有效性的質疑。"}]', '{"noun2":"recidivist","adjective":"recidivist"}', NULL, 4, 5441, NULL),
(5442, 'recipe', '/''resɪpi/', 'noun', '{"zh-TW":["食譜；烹飪方法"],"en":["a set of instructions for preparing a dish, including a list of ingredients"]}', NULL, 'follow a recipe / recipe book / traditional recipe', '[{"en":"She followed the recipe carefully to make her grandmother''s soup.","zh-TW":"她仔細按照食譜製作奶奶的湯。"},{"en":"The chef shared his secret recipe for the restaurant''s most popular dish.","zh-TW":"廚師分享了餐廳最受歡迎菜肴的秘密食譜。"}]', NULL, NULL, 2, 5442, NULL),
(5443, 'recipient', '/rɪˈsɪpiənt/', 'noun', '{"zh-TW":["接收者；收件人"],"en":["a person who receives something"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"cipient","meaning":"take (拿取)"}}', 'award recipient / email recipient / intended recipient', '[{"en":"The recipient of the award was announced.","zh-TW":"獎項得主已公佈。"},{"en":"Please confirm the recipient''s email address.","zh-TW":"請確認收件人的電郵地址。"}]', NULL, NULL, 3, 5443, NULL),
(5444, 'recognition', '/ˌrɛkəɡˈnɪʃən/', 'noun', '{"zh-TW":["認可；表彰","認出","認可；識別"],"en":["acknowledgment; appreciation","identifying someone","acknowledgment; the act of identifying"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cogn","meaning":"know (知道)"},"suffix":{"text":"-ition","meaning":"行為"}}', 'in recognition of / gain recognition / brand recognition', '[{"en":"She received recognition for her contributions.","zh-TW":"她因貢獻而獲得表彰。"},{"en":"Brand recognition has improved significantly.","zh-TW":"品牌認知度顯著提升。"},{"en":"She won recognition for her work.","zh-TW":"她的工作獲得了認可。"},{"en":"Brand recognition is essential for growth.","zh-TW":"品牌認知對成長至關重要。"}]', '{"verb":"recognize","adjective":"recognizable"}', NULL, 4, 5444, 432),
(5445, 'recognize', '/ˈrɛkəɡnaɪz/', 'verb', '{"zh-TW":["認出；承認","認可"],"en":["to identify","to acknowledge"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cogn","meaning":"know (知道)"},"suffix":{"text":"-ize","meaning":"使..."}}', 'recognize the importance / widely recognized / recognize sb.', '[{"en":"We recognize the need for improvement.","zh-TW":"我們認識到需要改進。"},{"en":"She is widely recognized as an expert.","zh-TW":"她被廣泛認為是專家。"}]', '{"noun":"recognition","adjective":"recognizable"}', NULL, 3, 5445, 192),
(5446, 'recommend', '/ˌrɛkəˈmɛnd/', 'verb', '{"zh-TW":["推薦；建議"],"en":["to suggest as good; to advise"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"commend","meaning":"praise (讚美)"}}', 'highly recommend / recommend that / recommend sb. for', '[{"en":"I highly recommend this software.","zh-TW":"我強力推薦這個軟體。"},{"en":"The committee recommends that we proceed.","zh-TW":"委員會建議我們繼續。"}]', '{"noun":"recommendation"}', NULL, 3, 5446, 50),
(5447, 'recommendation', 'ˌrɛkəmɛnˈdeɪʃən', 'noun', '{"zh-TW":["建議；推薦","意見"],"en":["advice given","a positive suggestion"]}', NULL, 'make a recommendation/follow recommendations', '[{"en":"The committee made several recommendations.","zh-TW":"委員會提出了幾項建議。"}]', '{"verb":"recommend","adjective":"recommended"}', NULL, 5, 5447, 612),
(5448, 'reconcile', '/ˈrɛkənsaɪl/', 'verb', '{"zh-TW":["調和；使一致"],"en":["to make compatible; to settle differences"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"concile","meaning":"bring together (聚集)"}}', 'reconcile differences / reconcile accounts / hard to reconcile', '[{"en":"We need to reconcile the accounts by month-end.","zh-TW":"我們需要在月底前核對帳目。"},{"en":"It''s hard to reconcile the conflicting reports.","zh-TW":"很難調和相互矛盾的報告。"}]', '{"noun":"reconciliation"}', NULL, 3, 5448, 711),
(5449, 'reconcile accounts', '/ˈrekənsaɪl əˈkaʊnts/', 'verb', '{"zh-TW":["對帳；使帳戶一致"],"en":["to compare and match financial records to ensure they are correct"]}', NULL, 'reconcile bank accounts / reconcile accounts monthly', '[{"en":"The accountant reconciles accounts at the end of every month.","zh-TW":"會計師在每月末對帳。"},{"en":"Reconciling accounts helps detect errors and fraud.","zh-TW":"對帳有助於發現錯誤和欺詐。"}]', '{"noun":"reconciliation"}', NULL, 5, 5449, NULL);